#!/usr/bin/env python3
"""Run one exact-build RDF4J A/B transaction across a volatile-NBD power cut."""
# Some portions generated by Codex
from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import signal
import subprocess
import sys
from typing import Any

from runner_common import (
    add_seed_iso_builder_argument,
    backend_control,
    build_artifact_manifest,
    copy_and_hash,
    copy_file_exclusive,
    create_fresh_directory,
    create_qcow_overlay,
    create_seed_iso,
    fence_nbd_then_stop_guest,
    guest_classpath,
    guest_qemu_arguments,
    require_executable,
    require_free_tcp_ports,
    require_regular_file,
    resolve_seed_iso_builder,
    sha256_file,
    start_backend,
    start_logged_process,
    stop_process,
    wait_for_path,
    write_json_exclusive,
    write_text_exclusive,
)

SCRIPT_DIR = Path(__file__).resolve().parent
GUEST_DIR = SCRIPT_DIR / "guest"
DATA_BYTES = 128 * 1024 * 1024
SCENARIOS = {
    "mixed-replay-before-native-commit": {
        "cutpoint": "AFTER_FULL_REPLAY_BEFORE_AUTHORITATIVE_COMMIT",
        "commit_invoked": True,
        "native_commit_returned": False,
        "allowed_outcomes": ("A",),
        "description": "full mixed-transaction replay inside commit before native TripleStore commit",
    },
    "dictionary-before-triple-commit": {
        "cutpoint": "AFTER_DICTIONARY_COMMIT_BEFORE_TRIPLESTORE_COMMIT",
        "commit_invoked": True,
        "native_commit_returned": False,
        "allowed_outcomes": ("A",),
        "description": "dictionary commit returned before TripleStore namespace/RDF publication",
    },
    "commit-returned-before-ack": {
        "cutpoint": "AFTER_CONNECTION_COMMIT_RETURNED_BEFORE_B_ACK",
        "commit_invoked": True,
        "native_commit_returned": True,
        "allowed_outcomes": ("A_PLUS_B",),
        "description": "connection commit returned durably but external B acknowledgment was not written",
    },
}
PRESERVED_WITNESS_NAMES = (
    "actual-A-payload-child.tsv",
    "actual-A-ack-witness.tsv",
    "actual-A-commit-ack.json",
    "actual-B-payload-child.tsv",
    "actual-B-attempt-witness.tsv",
    "actual-B-commit-invoked-child.marker",
    "actual-B-commit-invoked-witness.marker",
    "actual-B-native-commit-returned-child.marker",
    "actual-B-native-commit-returned-witness.marker",
    "actual-cutpoint-child.marker",
    "actual-cutpoint-child-witness.txt",
    "actual-cutpoint-witness.json",
    "actual-powercut-scenario.txt",
    "actual-powercut-writer-controller.log",
    "actual-powercut-writer-events.jsonl",
)


def scenario_contract(scenario: str) -> dict[str, Any]:
    try:
        return SCENARIOS[scenario]
    except KeyError as error:
        raise ValueError(f"unknown scenario: {scenario}") from error


def validate_cutpoint_witness(scenario: str, witness: dict[str, Any], *, b_acknowledged: bool) -> None:
    contract = scenario_contract(scenario)
    if witness.get("scenario") != scenario or witness.get("cutpoint") != contract["cutpoint"]:
        raise ValueError("cutpoint witness does not match the requested scenario")
    if witness.get("A_acknowledged") is not True or witness.get("B_attempted") is not True:
        raise ValueError("cutpoint requires the exact acknowledged A and attempted B payloads")
    if witness.get("B_commit_invoked") is not contract["commit_invoked"]:
        raise ValueError("B_COMMIT_INVOKED marker contradicts the requested cutpoint")
    if witness.get("B_native_commit_returned") is not contract["native_commit_returned"]:
        raise ValueError("native commit return marker contradicts the requested cutpoint")
    if b_acknowledged or witness.get("B_acknowledged") is not False:
        raise ValueError("B must remain unacknowledged at all requested cutpoints")


def validate_recovery_pair(scenario: str, first: dict[str, Any], second: dict[str, Any]) -> None:
    allowed = scenario_contract(scenario)["allowed_outcomes"]
    for label, result in (("first", first), ("second", second)):
        if result.get("outcome") not in allowed:
            raise ValueError(f"{label} recovery outcome {result.get('outcome')} is not allowed")
        if not result.get("stateSha256"):
            raise ValueError(f"{label} recovery did not report an exact state hash")
    if first["outcome"] != second["outcome"]:
        raise ValueError("the same immutable crash image recovered to different transaction outcomes")
    if first["stateSha256"] != second["stateSha256"]:
        raise ValueError("the same immutable crash image recovered to different complete states")


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--scenario", choices=tuple(SCENARIOS), required=True,
                        help="deterministic cut point and its allowed transaction outcome")
    parser.add_argument("--scratch-root", required=True, type=Path,
                        help="new, non-existing directory for images, witnesses, and logs")
    parser.add_argument("--repo-root", required=True, type=Path,
                        help="RDF4J checkout with exact compiled target/classes and .m2_repo")
    parser.add_argument("--host-classpath-file", required=True, type=Path,
                        help="one-line classpath captured from the exact compiled LMDB test build")
    parser.add_argument("--os-base-image", required=True, type=Path,
                        help="provisioned Ubuntu guest qcow2 containing Java 25 and ext4 tools")
    parser.add_argument("--firmware-code", required=True, type=Path, help="read-only UEFI code image")
    parser.add_argument("--firmware-vars-template", required=True, type=Path,
                        help="disposable UEFI vars template")
    parser.add_argument("--qemu", required=True, type=Path, help="QEMU system emulator executable")
    parser.add_argument("--qemu-img", required=True, type=Path, help="qemu-img executable")
    add_seed_iso_builder_argument(parser)
    parser.add_argument("--port-base", required=True, type=int,
                        help="available localhost TCP port; next port is reused for both recoveries")
    parser.add_argument("--machine", choices=("virt", "q35"), default="virt")
    parser.add_argument("--accel", default="hvf", help="QEMU accelerator (default: hvf)")
    parser.add_argument("--cpu", default="host", help="QEMU CPU model (default: host)")
    parser.add_argument("--native-classifier", choices=("linux", "linux-arm64", "linux-ppc64le"),
                        default="linux-arm64", help="Linux LWJGL native classifier used by the guest")
    parser.add_argument("--smp", type=int, default=4)
    parser.add_argument("--memory-mib", type=int, default=4096)
    parser.add_argument("--writer-timeout-seconds", type=int, default=480)
    parser.add_argument("--recovery-timeout-seconds", type=int, default=480)
    parser.add_argument("--cut-seed", type=int, default=20260927)
    return parser.parse_args()


def validate_inputs(args: argparse.Namespace) -> dict[str, Any]:
    contract = scenario_contract(args.scenario)
    repo = args.repo_root.expanduser().resolve(strict=True)
    if not repo.is_dir() or not (repo / ".m2_repo").is_dir():
        raise FileNotFoundError("repository root and its .m2_repo must exist")
    seed_iso_tool, seed_iso_builder = resolve_seed_iso_builder(args)
    inputs: dict[str, Any] = {
        "repo_root": repo,
        "qemu": require_executable(args.qemu, "QEMU"),
        "qemu_img": require_executable(args.qemu_img, "qemu-img"),
        "seed_iso_tool": require_executable(seed_iso_tool, seed_iso_builder),
        "seed_iso_builder": seed_iso_builder,
        "os_image": require_regular_file(args.os_base_image, "OS base image"),
        "firmware_code": require_regular_file(args.firmware_code, "UEFI code image"),
        "firmware_vars": require_regular_file(args.firmware_vars_template, "UEFI vars template"),
        "classpath_file": require_regular_file(args.host_classpath_file, "host classpath file"),
        "backend": require_regular_file(repo / "scripts/lmdb-crashlab/volatile_nbd.py", "NBD backend"),
    }
    inputs["artifact_manifest"] = build_artifact_manifest(repo)
    inputs["classpath_value"], inputs["classpath_manifest"] = guest_classpath(
        inputs["classpath_file"], repo, native_classifier=args.native_classifier)
    if not 1 <= args.port_base <= 65534:
        raise ValueError("--port-base must allow writer and recovery ports in range")
    require_free_tcp_ports("127.0.0.1", (args.port_base, args.port_base + 1))
    if args.smp < 1 or args.memory_mib < 1024:
        raise ValueError("guest must have at least one CPU and 1024 MiB RAM")
    if args.writer_timeout_seconds < 1 or args.recovery_timeout_seconds < 1:
        raise ValueError("guest timeouts must be positive")
    return inputs


def create_blank_image(path: Path, size: int) -> None:
    with path.open("xb") as stream:
        stream.truncate(size)
        stream.flush()
        os.fsync(stream.fileno())


def replace_text_fsynced(path: Path, value: str) -> None:
    temporary = path.with_name(path.name + ".new")
    if temporary.exists() or temporary.is_symlink():
        raise FileExistsError(f"refusing preexisting control file: {temporary}")
    with temporary.open("x", encoding="utf-8") as stream:
        stream.write(value)
        stream.flush()
        os.fsync(stream.fileno())
    os.replace(temporary, path)
    fd = os.open(path.parent, os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def prepare_guest_inputs(root: Path, inputs: dict[str, Any], args: argparse.Namespace) -> dict[str, Any]:
    contract = scenario_contract(args.scenario)
    results, qemu_root, nbd_root, data_root = (root / "results", root / "qemu", root / "nbd", root / "data")
    for directory in (results, qemu_root, nbd_root, data_root):
        directory.mkdir()
    copy_file_exclusive(inputs["classpath_file"], results / "actual-build-classpath-host.txt")
    write_text_exclusive(results / "actual-build-classpath-guest.txt", inputs["classpath_value"] + "\n")
    write_json_exclusive(results / "actual-current-build-manifest.json", inputs["artifact_manifest"])
    write_json_exclusive(results / "actual-classpath-manifest.json", inputs["classpath_manifest"])
    write_text_exclusive(results / "actual-powercut-scenario.txt", args.scenario + "\n")
    write_text_exclusive(results / "actual-active-recovery-run.txt", "1\n")
    image = data_root / "data.raw"
    create_blank_image(image, DATA_BYTES)

    writer_os = qemu_root / "writer-os.qcow2"
    recovery_os = [qemu_root / "recovery-1-os.qcow2", qemu_root / "recovery-2-os.qcow2"]
    create_qcow_overlay(inputs["qemu_img"], inputs["os_image"], writer_os,
                        qemu_root / "writer-os-overlay.log")
    for index, overlay in enumerate(recovery_os, start=1):
        create_qcow_overlay(inputs["qemu_img"], inputs["os_image"], overlay,
                            qemu_root / f"recovery-{index}-os-overlay.log")
    writer_vars = qemu_root / "writer-vars.fd"
    recovery_vars = [qemu_root / "recovery-1-vars.fd", qemu_root / "recovery-2-vars.fd"]
    copy_file_exclusive(inputs["firmware_vars"], writer_vars)
    for vars_file in recovery_vars:
        copy_file_exclusive(inputs["firmware_vars"], vars_file)
    writer_seed = create_seed_iso(inputs["seed_iso_tool"], qemu_root, "powercut-writer", "boot-powercut-writer.sh",
                                  builder=inputs["seed_iso_builder"])
    recovery_seeds = [
        create_seed_iso(inputs["seed_iso_tool"], qemu_root, "powercut-recovery-1", "boot-powercut-recovery.sh",
                        builder=inputs["seed_iso_builder"]),
        create_seed_iso(inputs["seed_iso_tool"], qemu_root, "powercut-recovery-2", "boot-powercut-recovery.sh",
                        builder=inputs["seed_iso_builder"]),
    ]
    sources = [
        inputs["backend"], SCRIPT_DIR / "run_powercut_campaign.py", SCRIPT_DIR / "runner_common.py",
        GUEST_DIR / "CrashPowerCutFixtures.java", GUEST_DIR / "CrashPowerCutWriterMain.java",
        GUEST_DIR / "CrashPowerCutOracleMain.java", GUEST_DIR / "powercut-writer-controller.py",
        GUEST_DIR / "boot-powercut-writer.sh", GUEST_DIR / "boot-powercut-recovery.sh",
        GUEST_DIR / "bootstrap-user-data.yaml.in",
    ]
    source_hashes = {str(path): sha256_file(path) for path in sources}
    manifest = {
        "scenario": args.scenario,
        "scenario_contract": contract,
        "repo_root": str(inputs["repo_root"]),
        "os_base_image": str(inputs["os_image"]),
        "os_base_image_sha256": sha256_file(inputs["os_image"]),
        "firmware_code": str(inputs["firmware_code"]),
        "firmware_code_sha256": sha256_file(inputs["firmware_code"]),
        "firmware_vars_template": str(inputs["firmware_vars"]),
        "firmware_vars_template_sha256": sha256_file(inputs["firmware_vars"]),
        "checked_in_volatile_nbd_backend": str(inputs["backend"]),
        "checked_in_volatile_nbd_backend_sha256": source_hashes[str(inputs["backend"])],
        "source_hashes": source_hashes,
        "raw_data_image": str(image),
        "raw_data_image_size_bytes": DATA_BYTES,
        "raw_data_image_initial_sha256": sha256_file(image),
        "writer_os_overlay": str(writer_os),
        "recovery_os_overlays": [str(path) for path in recovery_os],
        "writer_seed_iso": str(writer_seed),
        "recovery_seed_isos": [str(path) for path in recovery_seeds],
        "writer_and_recovery_use_same_compiled_manifest": True,
        "repository_and_m2_shares_read_only": True,
        "independent_witness_share": "host-backed writable 9p results share",
        "data_cache_contract": "QEMU writeback with virtio write-cache on; FLUSH/FUA not bypassed",
        "fault_boundary": "QEMU Linux guest, ext4, and volatile virtual NBD device loss; not physical host power loss",
    }
    write_json_exclusive(results / "actual-powercut-input-manifest.json", manifest)
    return {
        "results": results,
        "qemu_root": qemu_root,
        "nbd_root": nbd_root,
        "image": image,
        "writer_os": writer_os,
        "recovery_os": recovery_os,
        "writer_vars": writer_vars,
        "recovery_vars": recovery_vars,
        "writer_seed": writer_seed,
        "recovery_seeds": recovery_seeds,
        "source_hashes": source_hashes,
    }


def guest_command(inputs: dict[str, Any], args: argparse.Namespace, *, name: str, os_disk: Path,
                  vars_file: Path, port: int, seed: Path, serial: Path, results: Path) -> list[str]:
    return guest_qemu_arguments(
        qemu=inputs["qemu"], name=name, machine=args.machine, accel=args.accel,
        cpu=args.cpu, smp=args.smp,
        memory_mib=args.memory_mib, firmware_code=inputs["firmware_code"], firmware_vars=vars_file,
        os_disk=os_disk, data_port=port, seed_iso=seed, serial_log=serial,
        repo_root=inputs["repo_root"], results=results)


def launch_guest(command: list[str], results: Path, label: str) -> subprocess.Popen[bytes]:
    write_json_exclusive(results / f"actual-{label}-qemu-command.json", command)
    return start_logged_process(command, results / f"actual-{label}-qemu.log")


def run_recovery(index: int, source_image: Path, inputs: dict[str, Any], args: argparse.Namespace,
                 paths: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    results = paths["results"]
    recovery_id = str(index)
    working_dir = paths["root"] / f"working-recovery-{recovery_id}"
    working_dir.mkdir()
    image = working_dir / "data.raw"
    copy_record = copy_and_hash(source_image, image)
    replace_text_fsynced(results / "actual-active-recovery-run.txt", recovery_id + "\n")

    control = paths["nbd_root"] / f"recovery-{recovery_id}-control.sock"
    events = results / f"actual-recovery-{recovery_id}-nbd-events.jsonl"
    backend = None
    guest = None
    port = args.port_base + 1
    try:
        backend = start_backend(python=Path(sys.executable), backend=inputs["backend"], image=image,
                                control=control, port=port, events=events,
                                log=results / f"actual-recovery-{recovery_id}-backend.log",
                                command_record=results / f"actual-recovery-{recovery_id}-backend-command.json")
        initial = backend_control(Path(sys.executable), inputs["backend"], control, "status")
        write_json_exclusive(results / f"actual-recovery-{recovery_id}-backend-initial-status.json", initial)
        command = guest_command(
            inputs, args, name=f"rdf4j-powercut-recovery-{recovery_id}",
            os_disk=paths["recovery_os"][index - 1], vars_file=paths["recovery_vars"][index - 1],
            port=port, seed=paths["recovery_seeds"][index - 1],
            serial=results / f"actual-recovery-{recovery_id}-serial.log", results=results)
        guest = launch_guest(command, results, f"recovery-{recovery_id}")
        done = results / f"actual-recovery-{recovery_id}-done"
        failed = results / f"actual-recovery-{recovery_id}-failed"
        marker = wait_for_path(guest, (done, failed), args.recovery_timeout_seconds)
        if marker != done:
            failure = failed.read_text(encoding="utf-8", errors="replace")
            raise RuntimeError(f"public recovery {recovery_id} failed: {failure}")
        oracle_path = results / f"actual-recovery-{recovery_id}-oracle.json"
        oracle = json.loads(oracle_path.read_text(encoding="utf-8"))
        status = backend_control(Path(sys.executable), inputs["backend"], control, "status")
        write_json_exclusive(results / f"actual-recovery-{recovery_id}-backend-final-status.json", status)
        if guest.poll() is None:
            stop_process(guest, signal.SIGKILL)
        guest = None
        return oracle, {"image_copy": copy_record, "oracle": oracle,
                        "backend_initial": initial, "backend_final": status,
                        "image_after_recovery_sha256": sha256_file(image)}
    finally:
        stop_process(guest, signal.SIGKILL)
        stop_process(backend, signal.SIGINT)


def main() -> int:
    args = parse_args()
    inputs = validate_inputs(args)
    root = create_fresh_directory(args.scratch_root)
    paths = prepare_guest_inputs(root, inputs, args)
    paths["root"] = root
    contract = scenario_contract(args.scenario)
    baseline_hashes = {
        "backend": sha256_file(inputs["backend"]),
        "os_image": sha256_file(inputs["os_image"]),
        "classpath_file": sha256_file(inputs["classpath_file"]),
    }
    writer_backend = writer_guest = None
    failure: BaseException | None = None
    report: dict[str, Any] | None = None
    try:
        writer_control = paths["nbd_root"] / "writer-control.sock"
        writer_events_path = paths["results"] / "actual-writer-nbd-events.jsonl"
        writer_backend = start_backend(
            python=Path(sys.executable), backend=inputs["backend"], image=paths["image"],
            control=writer_control, port=args.port_base, events=writer_events_path,
            log=paths["results"] / "actual-writer-backend.log",
            command_record=paths["results"] / "actual-writer-backend-command.json")
        initial_status = backend_control(Path(sys.executable), inputs["backend"], writer_control, "status")
        write_json_exclusive(paths["results"] / "actual-writer-backend-initial-status.json", initial_status)
        writer_command = guest_command(
            inputs, args, name="rdf4j-powercut-writer", os_disk=paths["writer_os"],
            vars_file=paths["writer_vars"], port=args.port_base, seed=paths["writer_seed"],
            serial=paths["results"] / "actual-writer-serial.log", results=paths["results"])
        writer_guest = launch_guest(writer_command, paths["results"], "powercut-writer")
        marker = wait_for_path(
            writer_guest,
            (paths["results"] / "actual-cutpoint-witness.json",
             paths["results"] / "actual-powercut-writer-failed",
             paths["results"] / "actual-powercut-writer-setup-failed"),
            args.writer_timeout_seconds)
        if marker.name != "actual-cutpoint-witness.json":
            detail = marker.read_text(encoding="utf-8", errors="replace")
            raise RuntimeError(f"writer guest failed before the requested cutpoint: {detail}")
        cut_witness = json.loads(marker.read_text(encoding="utf-8"))
        validate_cutpoint_witness(args.scenario, cut_witness,
                                  b_acknowledged=(paths["results"] / "actual-B-acknowledged-witness.tsv").exists())
        writer_status = backend_control(Path(sys.executable), inputs["backend"], writer_control, "status")
        write_json_exclusive(paths["results"] / "actual-writer-backend-status-before-cut.json", writer_status)
        cut = fence_nbd_then_stop_guest(
            writer_guest,
            lambda: backend_control(Path(sys.executable), inputs["backend"], writer_control,
                                    "cut", "--survival", "drop", "--seed", str(args.cut_seed)),
        )
        writer_guest = None
        write_json_exclusive(paths["results"] / "actual-nbd-device-cut.json", cut)
        if not cut.get("off") or cut.get("survival") != "drop" or cut.get("kept_sectors") != 0:
            raise RuntimeError("NBD backend did not complete a volatile-sector drop cut")

        preserved_dir = paths["results"] / "pre-recovery-image"
        preserved_dir.mkdir()
        preserved = copy_and_hash(paths["image"], preserved_dir / "data.raw")
        preserved_witnesses: dict[str, Any] = {}
        for name in PRESERVED_WITNESS_NAMES:
            source = paths["results"] / name
            if source.is_file():
                preserved_witnesses[name] = copy_and_hash(source, preserved_dir / name)
        immutable_hash = sha256_file(preserved_dir / "data.raw")
        if immutable_hash != preserved["sha256"]:
            raise RuntimeError("preserved pre-recovery image hash changed immediately after copy")
        stop_process(writer_backend, signal.SIGINT)
        writer_backend = None

        first, first_details = run_recovery(1, preserved_dir / "data.raw", inputs, args, paths)
        second, second_details = run_recovery(2, preserved_dir / "data.raw", inputs, args, paths)
        validate_recovery_pair(args.scenario, first, second)
        preserved_hash_after = sha256_file(preserved_dir / "data.raw")
        if preserved_hash_after != immutable_hash:
            raise RuntimeError("a recovery run modified the immutable preserved NBD image")

        writer_events = [json.loads(line) for line in writer_events_path.read_text(encoding="utf-8").splitlines()
                         if line.strip()]
        report = {
            "result": "POWER_CUT_RECOVERY_STABLE",
            "scenario": args.scenario,
            "scenario_description": contract["description"],
            "scenario_contract": contract,
            "cutpoint_witness": cut_witness,
            "cut_report": cut,
            "writer_backend_status_before_cut": writer_status,
            "writer_backend_initial_status": initial_status,
            "writer_nbd_flush_done_count": sum(event.get("event") == "FLUSH_DONE" for event in writer_events),
            "writer_nbd_fua_done_count": sum(event.get("event") == "FUA_DONE" for event in writer_events),
            "pre_recovery_image": preserved,
            "pre_recovery_image_sha256_after_both_recoveries": preserved_hash_after,
            "external_witnesses": preserved_witnesses,
            "recovery_1": first_details,
            "recovery_2": second_details,
            "same_outcome_on_both_recoveries": first["outcome"] == second["outcome"],
            "same_full_state_hash_on_both_recoveries": first["stateSha256"] == second["stateSha256"],
            "B_acknowledged": False,
            "exact_build_manifest": str(paths["results"] / "actual-current-build-manifest.json"),
            "boundary": "QEMU Linux guest, ext4, and volatile virtual NBD device-loss behavior only; not physical host power loss",
        }
    except BaseException as error:
        failure = error
    finally:
        stop_process(writer_guest, signal.SIGKILL)
        stop_process(writer_backend, signal.SIGINT)

    source_hashes_after = {name: sha256_file(Path(name)) for name in paths["source_hashes"]}
    source_unchanged = source_hashes_after == paths["source_hashes"]
    after_inputs = {
        "backend": sha256_file(inputs["backend"]),
        "os_image": sha256_file(inputs["os_image"]),
        "classpath_file": sha256_file(inputs["classpath_file"]),
    }
    input_unchanged = after_inputs == baseline_hashes
    try:
        compiled_unchanged = build_artifact_manifest(inputs["repo_root"]) == inputs["artifact_manifest"]
        _, classpath_after = guest_classpath(
            inputs["classpath_file"], inputs["repo_root"], native_classifier=args.native_classifier)
        classpath_unchanged = classpath_after == inputs["classpath_manifest"]
    except (FileNotFoundError, ValueError):
        compiled_unchanged = classpath_unchanged = False
    if not (source_unchanged and input_unchanged and compiled_unchanged and classpath_unchanged):
        mutation = RuntimeError("a read-only harness, compiled, classpath, backend, or OS input changed")
        if failure is None:
            failure = mutation
    if failure is not None:
        failure_path = paths["results"] / "actual-powercut-campaign-failure.txt"
        if not failure_path.exists():
            write_text_exclusive(failure_path, type(failure).__name__ + ": " + str(failure) + "\n")
        write_json_exclusive(paths["results"] / "actual-powercut-campaign-report.json", {
            "result": "POWER_CUT_CAMPAIGN_FAILED",
            "scenario": args.scenario,
            "failure": type(failure).__name__ + ": " + str(failure),
            "read_only_sources_unchanged": source_unchanged,
            "compiled_artifacts_unchanged": compiled_unchanged,
            "classpath_artifacts_unchanged": classpath_unchanged,
            "input_files_unchanged": input_unchanged,
        })
        raise failure
    assert report is not None
    report["read_only_sources_unchanged"] = source_unchanged
    report["compiled_artifacts_unchanged"] = compiled_unchanged
    report["classpath_artifacts_unchanged"] = classpath_unchanged
    report["input_files_unchanged"] = input_unchanged
    report["pre_recovery_image_sha256_after_run"] = sha256_file(paths["results"] / "pre-recovery-image/data.raw")
    write_json_exclusive(paths["results"] / "actual-powercut-campaign-report.json", report)
    print(json.dumps(report, indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
